import React from 'react';

const Contact = () => {
    const sectionStyle = {
        padding: '2rem',
        backgroundColor: '#f9f9f9',
        fontFamily: 'Arial, sans-serif',
        lineHeight: '1.6',
        maxWidth: '800px',
        margin: '2rem auto',
        borderRadius: '8px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        textAlign: 'center',
    };

    const headingStyle = {
        fontSize: '2.5rem',
        color: '#333',
        marginBottom: '1.5rem',
    };

    const paragraphStyle = {
        fontSize: '1.2rem',
        color: '#555',
        marginBottom: '1rem',
    };

    const linkStyle = {
        color: '#007bff',
        textDecoration: 'none',
        fontSize: '1.2rem',
        margin: '0 0.5rem',
        transition: 'color 0.3s',
    };

    const linkHoverStyle = {
        color: '#0056b3',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>Contact</h1>
            <p style={paragraphStyle}>Email: <a style={linkStyle}>duclayankrizstianmarco79@gmail.com</a></p>
            <p>
                <a
                    href="https://www.facebook.com/pogi.dragon/"
                    target="_blank"
                    rel="noopener noreferrer"
                    style={linkStyle}
                    onMouseOver={(e) => (e.target.style.color = linkHoverStyle.color)}
                    onMouseOut={(e) => (e.target.style.color = linkStyle.color)}
                >
                    Facebook
                </a>
                |
                <a
                    href="https://github.com/KMarcoD"
                    target="_blank"
                    rel="noopener noreferrer"
                    style={linkStyle}
                    onMouseOver={(e) => (e.target.style.color = linkHoverStyle.color)}
                    onMouseOut={(e) => (e.target.style.color = linkStyle.color)}
                >
                    GitHub
                </a>
            </p>
        </section>
    );
};

export default Contact;
